"""Recognize only the financial back-links generated by this settlement."""
from datetime import datetime
from zoneinfo import ZoneInfo


def _verified(value):
    return value is True or (isinstance(value, dict) and value.get('fields') is True
                             and value.get('attachments') is True)


def owned_progress(before, after, record, child_id, same):
    def equal(key, left, right):
        if key != 'DATA PGTO EFETUADO' or not left or not right:
            return same(key, left, right)
        def day(value):
            parsed = datetime.fromisoformat(str(value).replace('Z', '+00:00'))
            if parsed.tzinfo is not None:
                parsed = parsed.astimezone(ZoneInfo('America/Sao_Paulo'))
            return parsed.date()
        try: return day(left) == day(right)
        except ValueError: return False
    launch = record.get('launch_item') or {}
    order = record.get('related_item') or {}
    fields = launch.get('expected_fields') or {}
    if (not _verified(launch.get('verified')) or not _verified(order.get('verified'))
            or launch.get('target_list') != 'LANCAMENTOS'
            or order.get('target_list') != 'NOTASPENDENTES'
            or str(fields.get('IDPGTOAGENDADO')) != str(child_id)
            or str(fields.get('AGRUPAR')) != str(order.get('item_id'))):
        return False
    for key in ('FORNECEDOR', 'FILIAL'):
        if not before.get(key) or not same(key, before[key], fields.get(key)):
            return False
    allowed = {'IDPEDIDO': str(order['item_id']), 'IDLANCAMENTOS': str(launch['item_id']),
               'DATA PGTO EFETUADO': fields.get('DATA PGTO EFETUADO'),
               'STATUS': 'PAGAMENTO EFETUADO'}
    return all(equal(key, value, after.get(key)) or (
        key in allowed and allowed[key] is not None and equal(key, allowed[key], after.get(key)))
        for key, value in before.items())
